mapper.select:
/* UserTransferMapper.selectSiteExists */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SITE S
     WHERE S.CMPNY_CD = #{cmpnyCd}
       AND S.SITE_CD  = #{siteCd}
     LIMIT 1
) T

/* UserTransferMapper.selectNodeExists */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SITE_NODE N
     WHERE N.CMPNY_CD = #{cmpnyCd}
       AND N.SITE_CD  = #{siteCd}
       AND N.NODE_CD  = #{nodeCd}
     LIMIT 1
) T

/* UserTransferMapper.selectIsSiteAdmin */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_SITE S
     WHERE S.CMPNY_CD      = #{cmpnyCd}
       AND S.SITE_CD       = #{siteCd}
       AND S.SITE_ADMIN_CD = #{userCd}
     LIMIT 1
) T

/* UserTransferMapper.selectLastAdminNodeCnt */
SELECT COUNT(*)
FROM TB_SITE_NODE N
WHERE N.CMPNY_CD = #{cmpnyCd}
  AND (
        N.MAIN_ADMIN_CD = #{userCd}
     OR N.SUB_ADMIN_CD  = #{userCd}
      )
  AND (NULLIF(TRIM(N.MAIN_ADMIN_CD), '') IS NULL OR N.MAIN_ADMIN_CD = #{userCd})
  AND (NULLIF(TRIM(N.SUB_ADMIN_CD), '')  IS NULL OR N.SUB_ADMIN_CD  = #{userCd})

/* UserTransferMapper.selectIsChkptManager */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_CHKPT_TYPE_MGMT M
     WHERE M.CMPNY_CD     = #{cmpnyCd}
       AND M.MGMT_USER_CD = #{userCd}
       AND M.USE_YN       = 'Y'
     LIMIT 1
) T

/* UserTransferMapper.selectFuturePendingHourlyReqCnt */
SELECT COUNT(*)
  FROM TB_USER_ATTD_REQ RQ
 WHERE RQ.CMPNY_CD   = #{cmpnyCd}
   AND RQ.USER_CD    = #{userCd}
   AND RQ.REQ_TYPE   = '05'
   AND RQ.REQ_STATUS = '01'
   AND RQ.DEL_YN     = 'N'
   AND RQ.START_TIME IS NOT NULL
   AND RQ.END_TIME   IS NOT NULL
   AND RQ.WORK_YMD  >=  #{moveDate}

/* UserTransferMapper.selectEffectiveSchSegment */
SELECT
      E.FST_SCH_STR_TIME   AS fstSchStrTime
    , E.FST_SCH_END_TIME   AS fstSchEndTime
    , E.SEC_SCH_STR_TIME   AS secSchStrTime
    , E.SEC_SCH_END_TIME   AS secSchEndTime
FROM (
    SELECT
          M.APPLY_DATE
        , M.FST_SCH_STR_TIME, M.FST_SCH_END_TIME
        , M.SEC_SCH_STR_TIME, M.SEC_SCH_END_TIME
    FROM TB_SCH_MGMT M
    WHERE M.CMPNY_CD = #{cmpnyCd}
      AND M.SITE_CD  = #{siteCd}
      AND M.SCH_CD   = #{schCd}
    UNION ALL
    SELECT
          H.APPLY_DATE
        , H.FST_SCH_STR_TIME, H.FST_SCH_END_TIME
        , H.SEC_SCH_STR_TIME, H.SEC_SCH_END_TIME
    FROM TB_SCH_MGMT_HIST H
    WHERE H.CMPNY_CD = #{cmpnyCd}
      AND H.SITE_CD  = #{siteCd}
      AND H.SCH_CD   = #{schCd}
) E
WHERE E.APPLY_DATE = (
    SELECT COALESCE(
             MAX(CASE WHEN SE.APPLY_DATE  <=  #{baseDate} THEN SE.APPLY_DATE END)
           , MIN(SE.APPLY_DATE)
           )
    FROM (
        SELECT M2.APPLY_DATE
        FROM TB_SCH_MGMT M2
        WHERE M2.CMPNY_CD = #{cmpnyCd}
          AND M2.SITE_CD  = #{siteCd}
          AND M2.SCH_CD   = #{schCd}
        UNION ALL
        SELECT H2.APPLY_DATE
        FROM TB_SCH_MGMT_HIST H2
        WHERE H2.CMPNY_CD = #{cmpnyCd}
          AND H2.SITE_CD  = #{siteCd}
          AND H2.SCH_CD   = #{schCd}
    ) SE
)
ORDER BY E.APPLY_DATE DESC
LIMIT 1

/* UserTransferMapper.selectActiveReservationCnt */
SELECT COUNT(*)
FROM (
    SELECT 1
      FROM TB_USER_TRANSFER_RESERVATION R
     WHERE R.CMPNY_CD = #{cmpnyCd}
       AND R.USER_CD  = #{userCd}
       AND R.STATUS   = 'RESERVED'
     LIMIT 1
) T

/* UserTransferMapper.selectReservationId */
SELECT CONCAT('TR', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'USER_TRANSFER'))
FROM DUAL

mapper.insert:
/* UserTransferMapper.insertReservation */
INSERT INTO TB_USER_TRANSFER_RESERVATION (
      CMPNY_CD
    , RESERVATION_ID
    , USER_CD
    , FROM_SITE_CD
    , FROM_NODE_CD
    , TO_SITE_CD
    , TO_NODE_CD
    , TO_DEFAULT_SCH_CD
    , MOVE_DATE
    , MOVE_REASON
    , EMPLOYMENT_TYPE
    , STATUS
    , NOTICE_ACK_YN
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
) VALUES (
      #{cmpnyCd}
    , #{reservationId}
    , #{userCd}
    , #{fromSiteCd}
    , #{fromNodeCd}
    , #{toSiteCd}
    , #{toNodeCd}
    , #{toDefaultSchCd}
    , #{moveDate}
    , #{moveReason}
    , #{employmentType}
    , 'RESERVED'
    , 'N'
    , 'N'
    , #{insertNo}
    , NOW()
)

mapper.select:
/* UserTransferMapper.selectReservationStatusForUpdate */
SELECT R.STATUS
FROM TB_USER_TRANSFER_RESERVATION R
WHERE R.CMPNY_CD       = #{cmpnyCd}
  AND R.RESERVATION_ID = #{reservationId}
FOR UPDATE

mapper.update:
/* UserTransferMapper.markReservationApplied */
UPDATE TB_USER_TRANSFER_RESERVATION
   SET STATUS        = 'APPLIED'
     , EXECUTED_DATE = NOW()
     , UPDATE_NO     = #{actor}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND RESERVATION_ID = #{reservationId}
   AND STATUS         = 'RESERVED'

/* UserTransferMapper.markReservationFailed */
UPDATE TB_USER_TRANSFER_RESERVATION
   SET STATUS      = 'FAILED'
     , FAIL_REASON = #{failReason}
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND RESERVATION_ID = #{reservationId}
   AND STATUS         = 'RESERVED'

/* UserTransferMapper.updateUserSiteNodeForTransfer */
UPDATE TB_USER
   SET SITE_CD = #{toSiteCd}
     , NODE_CD = #{toNodeCd}

     , DEFAULT_SCH_CD       = #{toDefaultSchCd}
     , DEFAULT_SCH_SET_DATE = NOW()

     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND USER_CD  = #{userCd}

/* UserTransferMapper.updateNodeMainAdminIfEmpty */
UPDATE TB_SITE_NODE
   SET MAIN_ADMIN_CD = #{userCd}
     , UPDATE_NO     = #{actor}
     , UPDATE_DATE   = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND SITE_CD  = #{siteCd}
   AND NODE_CD  = #{nodeCd}
   AND NULLIF(TRIM(MAIN_ADMIN_CD), '') IS NULL
   AND NULLIF(TRIM(SUB_ADMIN_CD), '')  IS NULL

