/* UserTransferMapper.cancelActiveAttdReqByApplicant */
UPDATE TB_USER_ATTD_REQ
   SET REQ_STATUS      = '04'
     , PROCESS_USER_CD = #{actor}
     , PROCESS_COMMENT = #{reason}
     , PROCESS_DATE    = NOW()
     , UPDATE_NO       = #{actor}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND USER_CD    = #{userCd}
   AND REQ_STATUS = '01'
   AND DEL_YN     = 'N'

/* UserTransferMapper.rejectAttdReqByReqIds */
UPDATE TB_USER_ATTD_REQ
   SET REQ_STATUS      = '03'
     , PROCESS_USER_CD = #{actor}
     , PROCESS_COMMENT = #{reason}
     , PROCESS_DATE    = NOW()
     , UPDATE_NO       = #{actor}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD   = #{cmpnyCd}
   AND REQ_STATUS = '01'
   AND DEL_YN     = 'N'
   AND REQ_ID IN

       #{rid}

/* UserTransferMapper.rejectApprovalStepsForApproverByReqIds */
UPDATE TB_USER_ATTD_REQ_APPROVAL
   SET APPROVAL_STATUS  = '03'
     , APPROVAL_COMMENT = #{reason}
     , APPROVAL_DATE    = NOW()
     , UPDATE_NO        = #{actor}
     , UPDATE_DATE      = NOW()
 WHERE CMPNY_CD         = #{cmpnyCd}
   AND APPROVER_USER_CD = #{userCd}
   AND APPROVAL_STATUS IN ('00', '01')
   AND REQ_ID IN

       #{rid}

/* UserTransferMapper.cancelActiveOvertimeByUser */
UPDATE TB_USER_OVERTIME_MGMT
   SET OT_STATUS   = 'CANCELLED'
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD  = #{cmpnyCd}
   AND USER_CD   = #{userCd}
   AND OT_STATUS = 'IN_PROGRESS'
   AND DEL_YN    = 'N'

/* UserTransferMapper.rejectActiveLeaveChangeByUser */
UPDATE TB_LEAVE_CHANGE_REQUEST
   SET REQ_STATUS      = 'REJECTED'
     , REJECT_REASON   = #{rejectReason}
     , CONFIRM_USER_CD = #{actor}
     , CONFIRM_DATE    = NOW()
     , UPDATE_NO       = #{actor}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD = #{cmpnyCd}
   AND (TARGET_USER_CD = #{userCd} OR INITIATOR_USER_CD = #{userCd})
   AND REQ_STATUS IN ('REQUESTED', 'AGREED')
   AND DEL_YN = 'N'

/* UserTransferMapper.endActiveTbmSessionsAsManager */
UPDATE TB_TBM_SESSION
   SET STATUS_CD   = 'COMPLETED'
     , ENDED_AT    = NOW()
     , UPDATE_NO   = #{actor}
     , UPDATE_DATE = NOW()
 WHERE CMPNY_CD        = #{cmpnyCd}
   AND MANAGER_USER_CD = #{userCd}
   AND DEL_YN          = 'N'
   AND STATUS_CD       = 'IN_PROGRESS'
   AND STARTED_AT   IS NOT NULL
   AND ENDED_AT     IS NULL
   AND CANCELLED_AT IS NULL

/* UserTransferMapper.markTbmAttendanceNotCompleted */
UPDATE TB_TBM_ATTENDANCE AT
   SET AT.COMPLETION_STATUS_CD = 'NOT_COMPLETED'
     , AT.NOT_COMPLETED_REASON = #{reason}
     , AT.STATUS_UPDATED_BY    = #{actor}
     , AT.STATUS_UPDATED_AT    = NOW()
     , AT.UPDATE_NO            = #{actor}
     , AT.UPDATE_DATE          = NOW()
 WHERE AT.CMPNY_CD = #{cmpnyCd}
   AND AT.USER_CD  = #{userCd}
   AND AT.DEL_YN   = 'N'
   AND AT.ENTRY_AT IS NOT NULL
   AND (AT.COMPLETION_STATUS_CD IS NULL OR AT.COMPLETION_STATUS_CD  <>  'COMPLETED')
   AND EXISTS (
        SELECT 1
          FROM TB_TBM_SESSION S
         WHERE S.CMPNY_CD     = AT.CMPNY_CD
           AND S.SESSION_CD   = AT.SESSION_CD
           AND S.DEL_YN       = 'N'
           AND S.CANCELLED_AT IS NULL
           AND S.ENDED_AT     IS NULL
       )

