/* UserTransferMapper.selectTransferNoticeByReservation */
SELECT


WHERE R.CMPNY_CD       = #{cmpnyCd}
  AND R.USER_CD        = #{userCd}
  AND R.RESERVATION_ID = #{reservationId}
  AND R.DEL_YN         = 'N'
LIMIT 1

/* UserTransferMapper.selectUnackedTransferNotice */
SELECT


WHERE R.CMPNY_CD      = #{cmpnyCd}
  AND R.USER_CD       = #{userCd}
  AND R.STATUS        IN ('RESERVED', 'APPLIED')
  AND R.NOTICE_ACK_YN = 'N'
  AND R.DEL_YN        = 'N'
ORDER BY R.INSERT_DATE DESC, R.RESERVATION_ID DESC
LIMIT 1

