/* UserTransferMapper.deleteFutureWorkPlansOnSite (F7/QT-11-8) */
DELETE FROM TB_USER_WORK_PLAN
 WHERE CMPNY_CD = #{cmpnyCd}
   AND SITE_CD  = #{fromSiteCd}
   AND USER_CD  = #{userCd}
   AND WORK_YMD  >=  #{fromYmd}

