/* UserTransferMapper.ackTransferNotice */
UPDATE TB_USER_TRANSFER_RESERVATION
   SET NOTICE_ACK_YN   = 'Y'
     , NOTICE_ACK_DATE = NOW()
     , UPDATE_NO       = #{userCd}
     , UPDATE_DATE     = NOW()
 WHERE CMPNY_CD       = #{cmpnyCd}
   AND RESERVATION_ID = #{reservationId}
   AND USER_CD        = #{userCd}
   AND DEL_YN         = 'N'
